"""Assertion evaluation engine for the eval suite."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Dict, List, Optional

from rasa.builder.copilot.mcp_server.tools.eval_config import LLMConfig
from rasa.e2e_test.assertions import Assertion, InvalidAssertionType
from rasa.e2e_test.e2e_config import BaseModelConfig, LLMJudgeConfig
from rasa.shared.core.events import (
    ActionExecuted,
    Event,
    FlowCancelled,
    FlowCompleted,
    FlowInterrupted,
    FlowStarted,
    SlotSet,
)

_SEQUENCING_KEY = "sequencing"

_STEP_MATCHERS = {
    "action_executed": lambda name, event: isinstance(event, ActionExecuted)
    and event.action_name == name,
    "slot_was_set": lambda name, event: isinstance(event, SlotSet)
    and event.key == name,
    "flow_started": lambda name, event: isinstance(event, FlowStarted)
    and event.flow_id == name,
    "flow_completed": lambda name, event: isinstance(event, FlowCompleted)
    and event.flow_id == name,
    "flow_cancelled": lambda name, event: isinstance(event, FlowCancelled)
    and event.flow_id == name,
    "flow_interrupted": lambda name, event: isinstance(event, FlowInterrupted)
    and event.flow_id == name,
}


@dataclass
class AssertionResult:
    """Result of evaluating a single assertion against a conversation."""

    assertion: Dict[str, Any]
    passed: bool
    detail: str


def _to_llm_judge_config(llm_config: LLMConfig) -> LLMJudgeConfig:
    """Build an ``LLMJudgeConfig`` from an eval ``LLMConfig``."""
    return LLMJudgeConfig(
        llm_config=BaseModelConfig(
            provider=llm_config.provider,
            model=llm_config.model,
            extra_parameters=dict(llm_config.model_extra or {}),
        )
    )


def _evaluate_sequencing(
    assertion_dict: Dict[str, Any], events: List[Event]
) -> AssertionResult:
    """Evaluate a sequencing assertion against the event list.

    Each step must match an event that appears strictly after the previous
    step's match in the conversation.
    """
    steps: List[Dict[str, Any]] = assertion_dict[_SEQUENCING_KEY]
    cursor = 0

    for step in steps:
        if not isinstance(step, dict) or len(step) != 1:
            raise InvalidAssertionType(
                f"sequencing step must be a single-key dict, got: {step!r}"
            )
        step_type, name = next(iter(step.items()))
        matcher = _STEP_MATCHERS.get(step_type)

        if matcher is None:
            raise InvalidAssertionType(step_type)

        match_index = next(
            (
                i
                for i, e in enumerate(events[cursor:], start=cursor)
                if matcher(name, e)
            ),
            None,
        )

        if match_index is None:
            return AssertionResult(
                assertion=assertion_dict,
                passed=False,
                detail=(
                    f"Sequencing failed: '{step_type}: {name}' not found"
                    f" after position {cursor} in the conversation."
                ),
            )

        cursor = match_index + 1

    return AssertionResult(assertion=assertion_dict, passed=True, detail="")


def evaluate_assertions(
    assertions: List[Dict[str, Any]],
    events: List[Event],
    llm_config: Optional[LLMConfig] = None,
    step_text: Optional[str] = None,
) -> List[AssertionResult]:
    """Evaluate assertions against the full conversation event list.

    Args:
        assertions: List of assertion dicts from the scenario goals.
        events: All events from the completed conversation.
        llm_config: LLM configuration for generative assertions. Required
            when the assertion list includes ``generative_response_is_relevant``
            or ``generative_response_is_grounded``; ignored otherwise.
        step_text: The user's last utterance. Required for
            ``generative_response_is_relevant`` assertions.

    Returns:
        One ``AssertionResult`` per assertion, in the same order.
    """
    llm_judge_config = _to_llm_judge_config(llm_config) if llm_config else None
    results: List[AssertionResult] = []

    for assertion_dict in assertions:
        if not isinstance(assertion_dict, dict) or len(assertion_dict) != 1:
            raise InvalidAssertionType(
                f"assertion must be a single-key dict, got: {assertion_dict!r}"
            )

        if _SEQUENCING_KEY in assertion_dict:
            results.append(_evaluate_sequencing(assertion_dict, events))
            continue

        assertion = Assertion.create_typed_assertion(assertion_dict)

        # prior_events contains all events before the current turn;
        # the simulation engine is responsible for splitting the tracker correctly.
        failure, _ = assertion.run(
            turn_events=events,
            prior_events=[],
            llm_judge_config=llm_judge_config,
            step_text=step_text,
        )

        if failure is not None:
            results.append(
                AssertionResult(
                    assertion=assertion_dict, passed=False, detail=failure.error_message
                )
            )
        else:
            results.append(
                AssertionResult(assertion=assertion_dict, passed=True, detail="")
            )

    return results
